use std::rc::Rc;

use dioxus::prelude::*;
use dioxus_field::{self as field, FieldContext, FieldMeta};
use dioxus_primitives::dioxus_attributes::attributes;
use dioxus_primitives::merge_attributes;

/// Whether [`Field`] emits the utilities that lay out its Compound parts.
///
/// daisyUI has no class for a Field's layout, so the default grid and spacing are
/// Tailwind utilities. [`FieldAppearance::None`] emits nothing so callers can
/// replace them without competing with utilities generated by the Registry
/// (ADR-0004).
#[derive(Copy, Clone, Debug, PartialEq, Default)]
#[non_exhaustive]
pub enum FieldAppearance {
    #[default]
    Default,
    None,
}

impl FieldAppearance {
    /// Every value of this axis, in the order the preview renders them.
    pub const ALL: &'static [Self] = &[Self::Default, Self::None];

    /// The Tailwind utilities for this value, as complete string literals so
    /// Tailwind's scanner can see them.
    pub const fn class(self) -> &'static str {
        match self {
            Self::Default => "grid min-w-0 gap-2",
            Self::None => "",
        }
    }
}

